<template><div class="page"><div class="page-head"><div><h2>经营指标</h2><p>新增指标后，后端会触发风险规则检测；启用MQ时由消息消费者异步执行。</p></div><div><el-input-number v-model="filter.companyId" :min="1" placeholder="企业ID" style="width:130px;margin-right:8px"/><el-input v-model="filter.metricCode" placeholder="指标编码" style="width:150px;margin-right:8px"/><el-button @click="load">查询</el-button><el-button type="primary" v-if="auth.has('metric:write')" @click="visible=true">新增指标</el-button></div></div><el-table :data="rows" v-loading="loading" stripe><el-table-column prop="metricDate" label="日期" width="120"/><el-table-column prop="companyId" label="企业ID" width="90"/><el-table-column prop="metricCode" label="指标编码" width="160"/><el-table-column prop="metricName" label="指标名称"/><el-table-column prop="metricValue" label="指标值"/><el-table-column prop="unit" label="单位"/><el-table-column prop="sourceType" label="来源"/></el-table>
<el-dialog v-model="visible" title="新增经营指标" width="520px"><el-form label-width="90px"><el-form-item label="企业ID"><el-input-number v-model="form.companyId" :min="1"/></el-form-item><el-form-item label="日期"><el-date-picker v-model="form.metricDate" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="指标编码"><el-select v-model="form.metricCode" filterable allow-create style="width:100%"><el-option label="收入 REVENUE" value="REVENUE"/><el-option label="客户流失率 CHURN_RATE" value="CHURN_RATE"/><el-option label="投诉量 COMPLAINT_COUNT" value="COMPLAINT_COUNT"/><el-option label="新增客户 NEW_CUSTOMERS" value="NEW_CUSTOMERS"/><el-option label="毛利率 GROSS_MARGIN" value="GROSS_MARGIN"/></el-select></el-form-item><el-form-item label="指标名称"><el-input v-model="form.metricName"/></el-form-item><el-form-item label="指标值"><el-input-number v-model="form.metricValue" :precision="2" style="width:100%"/></el-form-item><el-form-item label="单位"><el-input v-model="form.unit"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存并检测风险</el-button></template></el-dialog></div></template>
<script setup>import{ref,onMounted}from'vue';import{ElMessage}from'element-plus';import{api}from'../api';import{useAuthStore}from'../stores/auth';const auth=useAuthStore();const rows=ref([]),loading=ref(false),visible=ref(false),filter=ref({companyId:null,metricCode:''});const form=ref({companyId:1,metricDate:new Date().toISOString().slice(0,10),metricCode:'CHURN_RATE',metricName:'客户流失率',metricValue:0.2,unit:'%',sourceType:'MANUAL'});async function load(){loading.value=true;try{const p={...filter.value};if(!p.companyId)delete p.companyId;if(!p.metricCode)delete p.metricCode;rows.value=(await api.metrics(p))||[]}finally{loading.value=false}}async function save(){await api.createMetric(form.value);ElMessage.success('已保存，风险检测任务已触发');visible.value=false;load()}onMounted(load)</script>
